#include "lexer.h"

#include "shared/error.h"
#include "shared/str.h"
#include <ctype.h>
#include <errno.h>
#include <stdlib.h>
#include <string.h>

// The Microsoft C/C++ extension for VS Code likes to complain about C23 features. So, we shut it.
#ifdef __INTELLISENSE__
#define constexpr const
#endif

// ===== Internal =====

#define LEX_EOF (-1)

#define INDENT_STACK_INIT_CAP 8

typedef struct {
    const char *name;
    token_type_t tok_val;
} kw_keyval;

static const kw_keyval KW_TABLE[] = {
    {"def", TOK_KW_DEF},
    {"do", TOK_KW_DO},
    {"Double", TOK_KW_DOUBLE},
    {"else", TOK_KW_ELSE},
    {"if", TOK_KW_IF},
    {"import", TOK_KW_IMPORT},
    {"Int", TOK_KW_INT},
    {"return", TOK_KW_RETURN},
    {"String", TOK_KW_STRING},
    {"then", TOK_KW_THEN},
    {"Unit", TOK_KW_UNIT},
    {"val", TOK_KW_VAL},
    {"var", TOK_KW_VAR},
    {"while", TOK_KW_WHILE},
    {"Boolean", TOK_KW_BOOL},
};

static constexpr size_t KW_TABLE_LEN = sizeof(KW_TABLE) / sizeof(KW_TABLE[0]);

/**
 * @brief Returns the character `offset` positions ahead of the current position without consuming
 * any input.
 * @param lex The pointer to the lexer to read from.
 * @param offset The distance from the current position (0 means the current character).
 *
 * @returns The character as an `unsigned char` converted to `int`, or `LEX_EOF` if the position
 * lies past the end of the source code.
 */
static int peek_at(const lexer_t *lex, size_t offset) {
    size_t peek_idx = lex->src_pos + offset;
    return peek_idx < str_len(lex->src) ? (unsigned char)str_cstr(lex->src)[peek_idx] : LEX_EOF;
}

/**
 * @brief Returns the current character without consuming it.
 * @param lex The pointer to the lexer to read from.
 *
 * @note The behavior is equivalent to the following call:
 * ```c
 * peek_at(lex, 0);
 * ```
 *
 * @returns The current character, or `LEX_EOF` at the end of the source code.
 */
static inline int peek(const lexer_t *lex) {
    return peek_at(lex, 0);
}

/**
 * @brief Consumes the current character and updates the source position accordingly.
 * @param lex The pointer to the lexer to read from.
 * @note Consuming `'\n'` moves the position to the first column of the next line; any other
 * character moves it one column to the right. At the end of the source code, nothing is consumed
 * and the position stays unchanged.
 *
 * @returns The consumed character, or `LEX_EOF` at the end of the source code.
 */
static int advance(lexer_t *lex) {
    int c = peek(lex);

    if (c == LEX_EOF) {
        return LEX_EOF;
    }

    lex->src_pos++;

    if (c == '\n') {
        lex->src_line++;
        lex->src_column = 1;
    } else {
        lex->src_column++;
    }

    return c;
}

/**
 * @brief Consumes the current character only if it equals `expect`.
 * @param lex The pointer to the lexer to read from.
 * @param expect The character expected at the current position.
 *
 * @returns `true` if the character matched and was consumed, `false` otherwise (no input is
 * consumed).
 */
static bool match_next(lexer_t *lex, char expect) {
    if (peek(lex) != expect) {
        return false;
    }

    advance(lex);

    return true;
}

/**
 * @brief Skips the rest of a (possibly nested) block comment, including its closing `*` + `/`.
 * @param lex The pointer to the lexer to read from. The opening `/` + `*` must already be consumed.
 * @param line The line of the comment's opening delimiter, used for error reporting.
 * @param col The column of the comment's opening delimiter, used for error reporting.
 *
 * @returns `true` if the comment spanned more than one line (contained a `'\n'`), `false`
 * otherwise.
 *
 * @throws Error 1 - The comment (or any comment nested in it) is not terminated before the end of
 * the source code.
 */
static bool skip_ml_comment(lexer_t *lex, size_t line, size_t col) {
    size_t depth     = 1;
    bool has_newline = false;

    while (depth > 0) {
        int c = advance(lex);
        if (c == LEX_EOF) {
            error_throw_compile(ERR_LEXICAL, line, col, "unterminated comment");
        } else if (c == '\n') {
            has_newline = true;
        } else if (c == '/' && match_next(lex, '*')) {
            depth++;
        } else if (c == '*' && match_next(lex, '/')) {
            depth--;
        }
    }

    return has_newline;
}

/**
 * @brief Skips the rest of a line comment.
 * @param lex The pointer to the lexer to read from. The opening `//` must already be consumed.
 * @note The terminating `'\n'` is left in the input, so that the layout layer can process it.
 */
static void skip_sl_comment(lexer_t *lex) {
    while (peek(lex) != '\n' && peek(lex) != LEX_EOF) {
        advance(lex);
    }
}

/**
 * @brief Skips a single insignificant element at the current position: one space, tab or `'\r'`
 * character, a line comment, or a block comment.
 * @param lex The pointer to the lexer to read from.
 * @param expect_eol Set to `true` if a multi-line block comment was skipped; left unchanged
 * otherwise.
 * @note A `'\n'` is never skipped, since it is significant for the layout layer.
 *
 * @returns `true` if an element was skipped, `false` if the current character starts no
 * insignificant element (no input is consumed).
 *
 * @throws Error 1 - An unterminated block comment.
 *
 * @todo Refactor (two functions seem ok, but at least check).
 */
static bool skip_one_insignificant(lexer_t *lex, bool *expect_eol) {
    int c = peek(lex);

    if (c == ' ' || c == '\t' || c == '\r') {
        advance(lex);
        return true;
    }

    if (c != '/') {
        return false;
    }

    int next = peek_at(lex, 1);
    if (next == '/') {
        advance(lex);
        advance(lex);
        skip_sl_comment(lex);
        return true;
    }
    if (next == '*') {
        size_t line = lex->src_line, col = lex->src_column;
        advance(lex);
        advance(lex);
        if (skip_ml_comment(lex, line, col)) {
            *expect_eol = true;
        }
        return true;
    }

    return false;
}

/**
 * @brief Skips all consecutive whitespace (except `'\n'`) and comments at the current position.
 * @param lex The pointer to the lexer to read from.
 * @note A multi-line block comment acts as a line break: `saw_newline` is set and, outside of
 * parentheses, the comment must be followed by the end of the line or of the source code.
 *
 * @throws Error 1 - An unterminated block comment, or a token following a multi-line block comment
 * on the same line outside of parentheses.
 */
static void skip_insignificant(lexer_t *lex) {
    bool expect_eol = false; // a multiline block comment was skipped

    while (skip_one_insignificant(lex, &expect_eol)) {
    }

    if (!expect_eol) {
        return;
    }

    lex->saw_newline = true;

    // Inside parentheses, a multiline comment is just whitespace.
    if (lex->parens_depth == 0 && peek(lex) != '\n' && peek(lex) != LEX_EOF) {
        error_throw_compile(ERR_LEXICAL,
                            lex->src_line,
                            lex->src_column,
                            "unexpected token after multiline comment");
    }
}

/**
 * @brief Scans a string literal, either a single-line one (`"..."`) or a multi-line one
 * (`"""..."""`).
 * @param lex The pointer to the lexer to read from. The opening `"` must already be consumed.
 * @param tok The token to be filled; its position must already be set. On success, its type is set
 * to `TOK_LIT_STRING` and `str_val` holds the literal's value (owned by the token).
 * @note Escape sequences (`\\`, `\"`, `\n`, `\r`, `\t`) are translated only in single-line strings.
 * The contents of multi-line strings are taken verbatim, and the closing delimiter is the last
 * three quotes of a sequence of quotes.
 *
 * @throws Error 1 - An unterminated string literal (a single-line one ends with a `'\n'` or the end
 * of the source code, a multi-line one with the end of the source code), or an invalid escape
 * sequence.
 * @throws Error 99 - Allocation failed.
 */
static void scan_string(lexer_t *lex, token_t *tok) {
    // Initial '"' has been processed.
    string_t res = STR_INIT;
    int c;

    if (peek(lex) == '"' && peek_at(lex, 1) == '"') {
        // Multi-line string handling.

        advance(lex);
        advance(lex);

        // The closing delimiter is the last three quotes.
        while (!(peek(lex) == '"' && peek_at(lex, 1) == '"' && peek_at(lex, 2) == '"' &&
                 peek_at(lex, 3) != '"')) {
            if (peek(lex) == LEX_EOF) {
                error_throw_compile(ERR_LEXICAL,
                                    tok->line,
                                    tok->column,
                                    "unterminated multiline string");
            }
            str_push(&res, (char)advance(lex));
        }

        advance(lex);
        advance(lex);
        advance(lex);
    } else {
        // Single-line string handling.

        while ((c = advance(lex)) != '"') {
            if (c == LEX_EOF || c == '\n') {
                error_throw_compile(ERR_LEXICAL,
                                    lex->src_line,
                                    lex->src_column,
                                    "unterminated string literal");
            }
            if (c == '\\') {
                switch (c = advance(lex)) {
                case '\\':
                    c = '\\';
                    break;
                case '"':
                    c = '"';
                    break;
                case 'n':
                    c = '\n';
                    break;
                case 'r':
                    c = '\r';
                    break;
                case 't':
                    c = '\t';
                    break;
                default:
                    error_throw_compile(ERR_LEXICAL,
                                        lex->src_line,
                                        lex->src_column,
                                        "unexpected escape sequence: '\\%c'",
                                        c);
                }
            }

            str_push(&res, c);
        }
    }

    tok->type    = TOK_LIT_STRING;
    tok->str_val = res;
}

/**
 * @brief Scans an annotation; the only valid one is `@main`.
 * @param lex The pointer to the lexer to read from. The opening `@` must already be consumed.
 * @param tok The token to be filled; its position must already be set. On success, its type is set
 * to `TOK_AT_MAIN`.
 *
 * @throws Error 1 - The `@` is not followed by `main`, or `main` is followed by a letter, a digit
 * or an underscore.
 */
static void scan_annotation(lexer_t *lex, token_t *tok) {
    int c;

    if (advance(lex) != 'm' || advance(lex) != 'a' || advance(lex) != 'i' || advance(lex) != 'n' ||
        (c = peek(lex)) == '_' || isalnum(c)) {
        error_throw_compile(ERR_LEXICAL, tok->line, tok->column, "invalid annotation");
    }

    tok->type = TOK_AT_MAIN;
}

/**
 * @brief Scans the remaining digits of a digit sequence, which may contain underscores.
 * @param lex The pointer to the lexer to read from. The last consumed character must be a digit.
 * @param tok The token being scanned, used for error reporting.
 * @param buf The buffer the scanned digits are appended to. Underscores are discarded.
 *
 * @throws Error 1 - A sequence of underscores is not followed by a digit.
 * @throws Error 99 - Allocation failed.
 */
static void scan_digit_tail(lexer_t *lex, const token_t *tok, string_t *buf) {
    while (true) {
        if (isdigit(peek(lex))) {
            str_push(buf, (char)advance(lex));
        } else if (peek(lex) == '_') {
            while (peek(lex) == '_') {
                advance(lex);
            }
            if (!isdigit(peek(lex))) {
                error_throw_compile(ERR_LEXICAL,
                                    tok->line,
                                    tok->column,
                                    "'_' must be between two digits");
            }
        } else {
            return;
        }
    }
}

/**
 * @brief Scans an `Int` or a `Double` number literal.
 * @param lex The pointer to the lexer to read from.
 * @param tok The token to be filled; its position must already be set. On success, its type is set
 * to either `TOK_LIT_INT` (with `int_val`) or `TOK_LIT_DOUBLE` (with `double_val`).
 * @param c The first (already consumed) character of the literal: a digit, or a `.` followed by a
 * digit.
 * @note The literal is a `Double` if it contains a fractional part, an exponent or the `d`/`D`
 * suffix. A `.` after an integer part counts as a fractional part only if a digit follows it;
 * otherwise, it is left in the input (e.g. for member access).
 *
 * @throws Error 1 - A malformed literal: a leading zero in a non-zero integer part, a misplaced
 * underscore, an exponent without digits, the literal being directly followed by a letter, a digit
 * or an underscore, or a value out of range.
 * @throws Error 99 - Allocation failed.
 */
static void scan_number(lexer_t *lex, token_t *tok, int c) {
    string_t buf   = STR_INIT;
    bool is_double = false;

    if (c == '.') {
        // DOT state: a cipher most follow.
        is_double = true;

        str_push(&buf, '.');
        str_push(&buf, (char)advance(lex));

        scan_digit_tail(lex, tok, &buf);
    } else {
        // INT / INT_ZERO state.
        str_push(&buf, (char)c);
        scan_digit_tail(lex, tok, &buf);

        if (str_cstr(&buf)[0] == '0' && str_len(&buf) > 1) {
            error_throw_compile(ERR_LEXICAL,
                                tok->line,
                                tok->column,
                                "non-zero literal must not start with '0'");
        }

        // VALMEM lookahead.
        if (peek(lex) == '.' && isdigit(peek_at(lex, 1))) {
            is_double = true;

            // '.'
            str_push(&buf, (char)advance(lex));
            // First digit.
            str_push(&buf, (char)advance(lex));

            scan_digit_tail(lex, tok, &buf);
        }
    }

    // Exponent.
    if (peek(lex) == 'e' || peek(lex) == 'E') {
        is_double = true;
        str_push(&buf, (char)advance(lex));

        if (peek(lex) == '+' || peek(lex) == '-') {
            str_push(&buf, (char)advance(lex));
        }

        if (!isdigit(peek(lex))) {
            error_throw_compile(ERR_LEXICAL,
                                tok->line,
                                tok->column,
                                "exponent requires at least one digit");
        }

        str_push(&buf, (char)advance(lex));
        scan_digit_tail(lex, tok, &buf);
    }

    // Suffix (not appended to buf).
    if (peek(lex) == 'd' || peek(lex) == 'D') {
        advance(lex);
        is_double = true;
    }

    // The number must not be followed by a character, a cipher, nor an underscore.
    int next = peek(lex);
    if (isalnum(next) || next == '_') {
        error_throw_compile(ERR_LEXICAL, tok->line, tok->column, "invalid number literal");
    }

    // Parse the number, since buf is valid and doesn't contain underscore suffix.
    char *end = nullptr;
    errno     = 0;

    if (is_double) {
        tok->type       = TOK_LIT_DOUBLE;
        tok->double_val = strtod(str_cstr(&buf), &end);
    } else {
        tok->type    = TOK_LIT_INT;
        tok->int_val = strtoll(str_cstr(&buf), &end, 10);
    }

    if (*end != '\0' || errno == ERANGE) {
        error_throw_compile(ERR_LEXICAL,
                            lex->src_line,
                            lex->src_column - buf.len,
                            "failed to convert number literal '%s'",
                            str_cstr(&buf));
    }

    str_free(&buf);
}

/**
 * @brief Scans an identifier, a keyword, or a boolean literal.
 * @param lex The pointer to the lexer to read from. The first character of the lexeme (a letter or
 * an underscore) must already be consumed.
 * @param tok The token to be filled; its position must already be set. Its type is set to the
 * matching keyword type, to `TOK_LIT_BOOL` (with `bool_val`) for `true`/`false`, or to `TOK_IDENT`
 * (with `str_val` holding the name, owned by the token).
 *
 * @throws Error 99 - Allocation failed.
 */
static void scan_ident(lexer_t *lex, token_t *tok) {
    size_t start = lex->src_pos - 1;

    while (isalnum(peek(lex)) || peek(lex) == '_') {
        advance(lex);
    }

    const char *begin = str_cstr(lex->src) + start;
    size_t len        = lex->src_pos - start;

    // Keywords.
    for (size_t i = 0; i < KW_TABLE_LEN; i++) {
        if (strlen(KW_TABLE[i].name) == len && strncmp(KW_TABLE[i].name, begin, len) == 0) {
            tok->type = KW_TABLE[i].tok_val;
            return;
        }
    }

    // Boolean literals.
    if (len == 4 && strncmp(begin, "true", 4) == 0) {
        tok->type     = TOK_LIT_BOOL;
        tok->bool_val = true;
        return;
    }
    if (len == 5 && strncmp(begin, "false", 5) == 0) {
        tok->type     = TOK_LIT_BOOL;
        tok->bool_val = false;
        return;
    }

    // Identifier.
    tok->type = TOK_IDENT;
    str_init_from_n(&tok->str_val, begin, len);
}

/**
 * @brief Scans a single non-layout token at the current position.
 * @param lex The pointer to the lexer to read from. Insignificant characters must already be
 * skipped and the current character must be neither `'\n'` nor `LEX_EOF` (both are handled by the
 * layout layer).
 * @note The `after_newline` flag of the returned token is not set; that is up to the caller.
 *
 * @returns The scanned token, positioned at its first character. Its ownership is transferred to
 * the caller.
 *
 * @throws Error 1 - An unexpected character or a malformed lexeme.
 * @throws Error 99 - Allocation failed.
 */
static token_t scan_token(lexer_t *lex) {
    token_t tok = {
        .line   = lex->src_line,
        .column = lex->src_column,
    };
    int c = advance(lex);

    switch (c) {
    case '+':
        tok.type = TOK_OP_PLUS;
        break;
    case '-':
        tok.type = TOK_OP_MINUS;
        break;
    case '*':
        tok.type = TOK_OP_STAR;
        break;
    case '/':
        // Comments are already filtered out at this point.
        tok.type = TOK_OP_SLASH;
        break;
    case '(':
        tok.type = TOK_SEP_LPAREN;
        break;
    case ')':
        tok.type = TOK_SEP_RPAREN;
        break;
    case ',':
        tok.type = TOK_SEP_COMMA;
        break;
    case ':':
        tok.type = TOK_SEP_COLON;
        break;
    case ';':
        tok.type = TOK_SEP_SEMI;
        break;
    case '=':
        tok.type = match_next(lex, '=') ? TOK_OP_EQ : TOK_OP_ASSIGN;
        break;
    case '!':
        tok.type = match_next(lex, '=') ? TOK_OP_NEQ : TOK_OP_NOT;
        break;
    case '<':
        tok.type = match_next(lex, '=') ? TOK_OP_LE : TOK_OP_LT;
        break;
    case '>':
        tok.type = match_next(lex, '=') ? TOK_OP_GE : TOK_OP_GT;
        break;
    case '&':
        if (!match_next(lex, '&')) {
            error_throw_compile(ERR_LEXICAL, tok.line, tok.column, "unexpected '&'");
        }
        tok.type = TOK_OP_AND;
        break;
    case '|':
        if (!match_next(lex, '|')) {
            error_throw_compile(ERR_LEXICAL, tok.line, tok.column, "unexpected '|'");
        }
        tok.type = TOK_OP_OR;
        break;
    case '"':
        scan_string(lex, &tok);
        break;
    case '@':
        scan_annotation(lex, &tok);
        break;
    case '.':
        if (isdigit(peek(lex))) {
            scan_number(lex, &tok, c);
        } else {
            tok.type = TOK_SEP_DOT;
        }
        break;
    default:
        if (isdigit(c)) {
            scan_number(lex, &tok, c);
        } else if (isalpha(c) || c == '_') {
            scan_ident(lex, &tok);
        } else {
            error_throw_compile(ERR_LEXICAL, tok.line, tok.column, "unexpected character '%c'", c);
        }
    }

    return tok;
}

// ===== Layout =====

// Layout tokens are: INDENT, DEDENT, NEWLINE, EOF.

/**
 * @brief Pushes an indentation level onto the indentation stack, growing it if necessary.
 * @param lex The pointer to the lexer whose stack is to be modified.
 * @param level The indentation level (the number of leading spaces) of the newly opened block.
 *
 * @throws Error 99 - Allocation failed.
 */
static void indent_push(lexer_t *lex, size_t level) {
    if (lex->indent_len == lex->indent_cap) {
        lex->indent_cap *= 2;
        lex->indent_stack = safe_realloc(lex->indent_stack, lex->indent_cap * sizeof(size_t));
    }
    lex->indent_stack[lex->indent_len++] = level;
}

/**
 * @brief Returns the indentation level of the innermost open block.
 * @param lex The pointer to the lexer to read from. Its indentation stack must not be empty.
 *
 * @returns The level on top of the indentation stack.
 */
static inline size_t indent_top(const lexer_t *lex) {
    return lex->indent_stack[lex->indent_len - 1];
}

/**
 * @brief Creates a layout token at the current position.
 * @param lex The pointer to the lexer to read the position and the `saw_newline` flag from.
 * @param type The type of the token; should be one of `TOK_INDENT`, `TOK_DEDENT`, `TOK_NEWLINE`
 * and `TOK_EOF`.
 *
 * @returns The created token. It owns no resources.
 */
static token_t layout_token(const lexer_t *lex, token_type_t type) {
    return (token_t){
        .type          = type,
        .line          = lex->src_line,
        .column        = lex->src_column,
        .after_newline = lex->saw_newline,
    };
}

/**
 * @brief Processes the start of a physical line: measures its indentation and updates the
 * indentation stack accordingly.
 * @param lex The pointer to the lexer to read from. It must be at the start of a line.
 * @param out The token to be filled if a `TOK_INDENT` is to be emitted; left unchanged otherwise.
 * @note Dedents are not emitted, only scheduled in `pending_dedents`. Blank lines (containing only
 * whitespace and comments) do not change the indentation and leave `at_line_start` set. Inside
 * parentheses, a non-blank line is a continuation line and does not change the indentation either.
 *
 * @returns `true` if `out` was filled with a `TOK_INDENT` to be emitted, `false` otherwise.
 *
 * @throws Error 1 - A tab used for indentation of a non-blank line, a continuation line not
 * indented more than its logical line, a dedent not matching any outer indentation level, or an
 * error while skipping comments.
 * @throws Error 99 - Allocation failed.
 */
static bool handle_line_start(lexer_t *lex, token_t *out) {
    size_t width = 0;
    while (peek(lex) == ' ') {
        advance(lex);
        width++;
    }

    size_t tab_line = lex->src_line, tab_col = lex->src_column;
    bool has_tab = peek(lex) == '\t';

    skip_insignificant(lex);

    int c = peek(lex);

    if (c == '\n' || c == LEX_EOF) {
        // A blank line: it does not change the indentation, `at_line_start` stays set.
        return false;
    }

    if (has_tab) {
        error_throw_compile(ERR_LEXICAL, tab_line, tab_col, "tab used for indentation");
    }

    lex->at_line_start = false;

    if (lex->parens_depth > 0) {
        // A continuation line inside parentheses: no INDENT/DEDENT, but it must be indented more
        // than the start of its logical line.
        if (width <= indent_top(lex)) {
            error_throw_compile(ERR_LEXICAL,
                                lex->src_line,
                                lex->src_column,
                                "continuation line must be indented more than its logical line");
        }
        return false;
    }

    if (width > indent_top(lex)) {
        indent_push(lex, width);
        *out = layout_token(lex, TOK_INDENT);
        return true;
    }

    while (width < indent_top(lex)) {
        lex->indent_len--;
        lex->pending_dedents++;
    }

    if (width != indent_top(lex)) {
        error_throw_compile(ERR_LEXICAL,
                            lex->src_line,
                            lex->src_column,
                            "dedent does not match any outer indentation level");
    }

    return false;
}

/**
 * @brief Produces the next token from the source code, including the layout tokens.
 * @param lex The pointer to the lexer to read from.
 * @note A `TOK_NEWLINE` is emitted only at the end of a logical line containing tokens, never
 * inside parentheses. At the end of the source code, the last logical line is closed, then a
 * `TOK_DEDENT` is emitted for each open block, then `TOK_EOF` is returned on every subsequent call.
 * The lookahead token is not considered; that is handled by `lexer_next`.
 *
 * @returns The next token. Its ownership is transferred to the caller.
 *
 * @throws Error 1 - Lexical error.
 * @throws Error 99 - Allocation failed.
 */
static token_t next_token(lexer_t *lex) {
    while (true) {
        if (lex->pending_dedents > 0) {
            lex->pending_dedents--;
            return layout_token(lex, TOK_DEDENT);
        }

        if (lex->at_line_start) {
            token_t indent;
            if (handle_line_start(lex, &indent)) {
                return indent;
            }
            if (lex->pending_dedents > 0) {
                continue;
            }
        }

        skip_insignificant(lex);

        int c = peek(lex);

        if (c == '\n') {
            token_t newline = layout_token(lex, TOK_NEWLINE);
            advance(lex);
            lex->saw_newline   = true;
            lex->at_line_start = true;

            // Inside parentheses and on blank lines, LF is just whitespace.
            if (lex->parens_depth == 0 && lex->line_has_tokens) {
                lex->line_has_tokens = false;
                return newline;
            }
            continue;
        }

        if (c == LEX_EOF) {
            // Close the last logical line, then all open blocks. Subsequently, EOF forever.
            if (lex->line_has_tokens) {
                lex->line_has_tokens = false;
                return layout_token(lex, TOK_NEWLINE);
            }
            if (lex->indent_len > 1) {
                lex->indent_len--;
                return layout_token(lex, TOK_DEDENT);
            }
            return layout_token(lex, TOK_EOF);
        }

        token_t tok       = scan_token(lex);
        tok.after_newline = lex->saw_newline;

        lex->saw_newline     = false;
        lex->line_has_tokens = true;

        if (tok.type == TOK_SEP_LPAREN) {
            lex->parens_depth++;
        } else if (tok.type == TOK_SEP_RPAREN && lex->parens_depth > 0) {
            // Unbalanced parentheses are reported by the parser, lexer has nothing to do with it.
            lex->parens_depth--;
        }

        return tok;
    }
}

// ===== Lexer =====

void lexer_init(lexer_t *lex, const string_t *src) {
    *lex = (lexer_t){
        .src           = src,
        .src_line      = 1,
        .src_column    = 1,
        .indent_stack  = safe_malloc(INDENT_STACK_INIT_CAP * sizeof(size_t)),
        .indent_len    = 1,
        .indent_cap    = INDENT_STACK_INIT_CAP,
        .at_line_start = true,
    };

    // Top level.
    lex->indent_stack[0] = 0;
}

void lexer_free(lexer_t *lex) {
    if (lex->has_lookahead) {
        token_free(&lex->lookahead);
        lex->has_lookahead = false;
    }

    free(lex->indent_stack);
    lex->indent_stack = nullptr;
    lex->indent_len   = 0;
    lex->indent_cap   = 0;
}

token_t lexer_next(lexer_t *lex) {
    if (lex->has_lookahead) {
        // Ownership of the lookahead moves to the caller.
        lex->has_lookahead = false;
        return lex->lookahead;
    }

    return next_token(lex);
}

const token_t *lexer_peek(lexer_t *lex) {
    if (!lex->has_lookahead) {
        lex->lookahead     = lexer_next(lex);
        lex->has_lookahead = true;
    }

    return &lex->lookahead;
}

void token_free(token_t *tok) {
    if (tok->type == TOK_IDENT || tok->type == TOK_LIT_STRING) {
        // Safe to call even after reset (as the method states).
        str_free(&tok->str_val);
    }
}

const char *token_type_name(token_type_t type) {
    switch (type) {
    // ===== Source code layout =====
    case TOK_INDENT:
        return "indentation";
    case TOK_DEDENT:
        return "dedentation";
    case TOK_NEWLINE:
        return "end of line";
    case TOK_EOF:
        return "end of file";

    // ===== Identifiers and literals =====
    case TOK_IDENT:
        return "identifier";
    case TOK_LIT_INT:
        return "integer literal";
    case TOK_LIT_DOUBLE:
        return "double literal";
    case TOK_LIT_STRING:
        return "string literal";
    case TOK_LIT_BOOL:
        return "boolean literal";

    // ===== Keywords =====
    case TOK_KW_IMPORT:
        return "'import'";
    case TOK_KW_DEF:
        return "'def'";
    case TOK_KW_IF:
        return "'if'";
    case TOK_KW_THEN:
        return "'then'";
    case TOK_KW_ELSE:
        return "'else'";
    case TOK_KW_WHILE:
        return "'while'";
    case TOK_KW_DO:
        return "'do'";
    case TOK_KW_RETURN:
        return "'return'";
    case TOK_KW_VAL:
        return "'val'";
    case TOK_KW_VAR:
        return "'var'";
    case TOK_KW_INT:
        return "'Int'";
    case TOK_KW_DOUBLE:
        return "'Double'";
    case TOK_KW_STRING:
        return "'String'";
    case TOK_KW_BOOL:
        return "'Boolean'";
    case TOK_KW_UNIT:
        return "'Unit'";

    // ===== Operators and separators =====
    case TOK_OP_PLUS:
        return "'+'";
    case TOK_OP_MINUS:
        return "'-'";
    case TOK_OP_STAR:
        return "'*'";
    case TOK_OP_SLASH:
        return "'/'";
    case TOK_OP_EQ:
        return "'=='";
    case TOK_OP_NEQ:
        return "'!='";
    case TOK_OP_LT:
        return "'<'";
    case TOK_OP_LE:
        return "'<='";
    case TOK_OP_GT:
        return "'>'";
    case TOK_OP_GE:
        return "'>='";
    case TOK_OP_ASSIGN:
        return "'='";
    case TOK_OP_NOT:
        return "'!'";
    case TOK_OP_AND:
        return "'&&'";
    case TOK_OP_OR:
        return "'||'";
    case TOK_SEP_LPAREN:
        return "'('";
    case TOK_SEP_RPAREN:
        return "')'";
    case TOK_SEP_COMMA:
        return "','";
    case TOK_SEP_COLON:
        return "':'";
    case TOK_SEP_SEMI:
        return "';'";
    case TOK_SEP_DOT:
        return "'.'";
    case TOK_AT_MAIN:
        return "'@main'";
    }

    return "unknown token";
}
